771	    if (!heroAct || !heroImg || reduced) return;
772	    var p = parseFloat(getComputedStyle(heroAct).getPropertyValue('--sc-p'));
773	    if (isNaN(p)) p = 0;
774	    p = Math.max(0, Math.min(1, p));
775	    var x = POOL_START[0] + (POOL_END[0] - POOL_START[0]) * p;
776	    var y = POOL_START[1] + (POOL_END[1] - POOL_START[1]) * p;
777	    heroImg.style.objectPosition = x.toFixed(2) + '% ' + y.toFixed(2) + '%';
778	  }
