782	     (act mode) or a self-measured local scroll span (local mode) and writes
783	     a monotonic translate3d offset. Never the kit's own data-sc-parallax
784	     (centred on progress 0.5, cannot reverse on-screen direction). */
785	  var vh0 = window.innerHeight;
786	  var motionEls = Array.prototype.map.call(document.querySelectorAll('[data-motion]'), function(el){
787	    var rect0 = el.getBoundingClientRect();
788	    return {
789	      el: el,
790	      panel: el.closest('[data-sc-act]'),
791	      dir: el.getAttribute('data-motion'),
792	      px: parseFloat(el.getAttribute('data-motion-px')) || 300,
793	      mode: el.getAttribute('data-motion-mode') || 'act',
794	      span: parseFloat(el.getAttribute('data-motion-span')) || 600,
795	      delay: parseFloat(el.getAttribute('data-motion-delay')) || 0,
796	      refTop: rect0.top + window.scrollY
797	    };
798	  });
799	
800	  function paintMotion(){
801	    for (var i = 0; i < motionEls.length; i++){
802	      var m = motionEls[i];
803	      var p;
804	      if (m.mode === 'local'){
805	        var start = m.refTop - vh0 + m.delay;
806	        p = (window.scrollY - start) / m.span;
807	      } else {
808	        if (!m.panel) continue;
809	        p = parseFloat(getComputedStyle(m.panel).getPropertyValue('--sc-p')) || 0;
810	      }
811	      p = Math.max(0, Math.min(1, p));
812	      var mag = p * m.px;
813	      var amt = (m.dir === 'sink') ? mag : -mag;
814	      m.el.style.transform = 'translate3d(0,' + amt.toFixed(1) + 'px,0)';
815	    }
816	  }
817	
818	  /* ---- ledger word-scrub: vintergatan's device, rebuilt inline ---------- */
819	  var chapter = document.getElementById('giant-section');
820	  var threadFill = document.getElementById('threadFill');
821	  var allWords = [];
822	
823	  function wrapWords(el){
824	    var text = el.textContent;
825	    var words = text.split(/\s+/).filter(Boolean);
826	    el.textContent = '';
827	    words.forEach(function(w, i){
828	      var span = document.createElement('span');
829	      span.className = 'w';
830	      span.textContent = w;
831	      el.appendChild(span);
832	      if (i < words.length - 1) el.appendChild(document.createTextNode(' '));
833	      allWords.push(span);
834	    });
835	  }
836	
837	  function armChapter(){
838	    if (reduced || !chapter) return;
839	    Array.prototype.forEach.call(chapter.querySelectorAll('.scrub-text h3, .scrub-text p'), wrapWords);
840	    chapter.classList.add('is-armed');
841	  }
842	  armChapter();
843	
844	  /* Fixed local scroll span (not the whole panel's own height, which grows
845	     with ledger content and pushed full completion out to nearly the
846	     moment the section leaves the top of the screen — every row read
847	     mid-transition, never settled). Same "local" idea as the thesis
848	     headline's own data-motion-mode: measured once at mount, ramps over a
849	     constant ~780px of scroll from the moment the section's top clears the
850	     bottom of the viewport, so the whole ledger is fully lit well before
851	     the reader reaches its last row on a normal scroll pace. */
852	  var chapterRefTop = null;
853	  if (chapter){ var cr0 = chapter.getBoundingClientRect(); chapterRefTop = cr0.top + window.scrollY; }
854	  function chapterP(){
855	    if (chapterRefTop === null) return 0;
856	    var vh = window.innerHeight;
857	    var start = chapterRefTop - vh;
858	    var span = 780;
859	    var raw = (window.scrollY - start) / span;
860	    return Math.max(0, Math.min(1, raw));
861	  }
862	
863	  function updateScrub(){
864	    if (reduced || !allWords.length) return;
865	    var t = chapterP();
866	    var n = allWords.length;
867	    for (var i = 0; i < n; i++) {
868	      var start = i / n, end = (i + 1) / n;
869	      var wp = Math.max(0, Math.min(1, (t - start) / (end - start)));
870	      allWords[i].style.opacity = (0.14 + wp * 0.86).toFixed(3);
871	    }
872	    if (threadFill) threadFill.style.transform = 'scaleY(' + t.toFixed(4) + ')';
873	  }
874	
875	  /* Guard reveals, per vintergatan's own "what to borrow": force everything
876	     visible on a timer regardless of where scroll math lands. */
877	  function scrubFailsafeAll(){
878	    if (reduced) return;
879	    allWords.forEach(function(w){ w.style.opacity = '1'; });
880	    if (threadFill) threadFill.style.transform = 'scaleY(1)';
881	  }
882	  function scrubFailsafeNearViewport(){
883	    if (reduced) return;
884	    var r = chapter && chapter.getBoundingClientRect();
885	    if (r && r.top < window.innerHeight * 1.4 && r.bottom > -window.innerHeight * 0.4) scrubFailsafeAll();
886	  }
887	  setTimeout(scrubFailsafeAll, 350);
888	  setTimeout(scrubFailsafeNearViewport, 1800);
889	  setTimeout(scrubFailsafeNearViewport, 6000);
890	
891	  if (reduced){
892	    /* Reduced motion: everything visible, no travel. Motion elements sit at
893	       their natural position; the hero pool holds its resting crop; the
894	       ledger's words and thread stay at their CSS finished state. */
895	  } else {
896	    var raf = null, frozen = false;
897	    window.__scFreezeMotion = function(){ frozen = true; };
898	    window.__scUnfreezeMotion = function(){ frozen = false; paintMotion(); paintHeroPool(); updateScrub(); };
899	    function schedule(){
900	      if (raf || frozen) return;
901	      raf = requestAnimationFrame(function(){ raf = null; if (!frozen){ paintMotion(); paintHeroPool(); updateScrub(); } });
902	    }
903	    window.addEventListener('scroll', schedule, { passive:true });
904	    window.addEventListener('resize', schedule);
905	    paintMotion(); paintHeroPool(); updateScrub();
906	  }
907	})();
908	</script>
909	</body>
910	</html>
